python3 -c "
import json
with open('/app/resources/treasury_bulletin_1990_06.json') as f:
    data = json.load(f)

# Find all elements related to ESF
def search_json(obj, path=''):
    if isinstance(obj, dict):
        for key, value in obj.items():
            new_path = f'{path}.{key}' if path else key
            if 'esf' in key.lower() or 'exchange' in key.lower() or 'german' in key.lower() or 'polish' in key.lower() or 'poland' in key.lower():
                print(f'{new_path}: {str(value)[:200]}')
            search_json(value, new_path)
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search_json(item, f'{path}[{i}]')

search_json(data)
"
